SELECT CASE WHEN customers.age >= 60 THEN 'high' WHEN customers.age >= 42 THEN 'mid' ELSE 'low' END AS age_bucket, MIN(shipments.cost) AS min_cost, SUM(CASE WHEN shipments.carrier = 'UPS' THEN 1 ELSE 0 END) AS ups_count FROM shipments LEFT JOIN orders ON shipments.order_id = orders.id LEFT JOIN customers ON orders.customer_id = customers.id WHERE shipments.order_id IS NOT NULL GROUP BY CASE WHEN customers.age >= 60 THEN 'high' WHEN customers.age >= 42 THEN 'mid' ELSE 'low' END
